insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_54_v1'
from (values
('127.311.d.1.A',3,'A parent sets firm limits, explains the reasons, and listens to the child''s point of view. Which parenting style is this?','["Authoritative", "Neglectful", "Permissive", "Authoritarian"]'::jsonb,0,'Authoritative parents combine warmth with clear, explained rules.','original'),
('127.311.d.1.A',4,'A parent demands strict obedience, gives few explanations, and shows little warmth. Which style does this describe?','["Authoritative", "Authoritarian", "Permissive", "Uninvolved"]'::jsonb,1,'Authoritarian parenting stresses obedience over discussion.','original'),
('127.311.d.1.B',3,'Which is a legal responsibility of parents?','["Paying for college", "Choosing the child''s friends", "Providing food, shelter, and medical care for their child", "Attending every school event"]'::jsonb,2,'Parents are legally required to meet a child''s basic needs.','original'),
('127.311.d.1.B',4,'A parent who repeatedly fails to supervise a young child may face legal action for:','["truancy", "slander", "trespassing", "neglect"]'::jsonb,3,'Failing to provide adequate supervision can be legally defined as neglect.','original'),
('127.311.d.1.C',3,'Which is a characteristic of a positive parent-child relationship?','["Mutual respect and open communication", "Constant criticism", "Fear of punishment", "Unpredictable rules"]'::jsonb,0,'Respect and communication build trust.','original'),
('127.311.d.1.C',4,'Expecting a 2-year-old to sit quietly through a long dinner is an example of:','["a developmentally appropriate rule", "an unrealistic expectation for the child''s age", "an age-appropriate chore", "a positive guidance technique"]'::jsonb,1,'Toddlers cannot sit still for long, so the expectation does not fit the stage.','original'),
('127.311.d.1.D',3,'Parents carry out their duty to educate children differently as the child grows. For an infant, this mostly means:','["choosing a college major", "assigning homework", "talking, singing, and reading aloud", "teaching algebra"]'::jsonb,2,'Early learning comes through language and interaction.','original'),
('127.311.d.1.D',4,'For a teenager, the educational role of a parent shifts toward:','["supervising nap time", "teaching the alphabet", "feeding with a spoon", "guiding decisions about school and career plans"]'::jsonb,3,'Parental guidance changes with each developmental stage.','original'),
('127.311.d.2.A',3,'A child who lived through a frightening event may show which sign of trauma?','["Sudden changes such as nightmares or withdrawal", "Improved sleep and appetite", "Steady calm routines", "Increased trust of strangers"]'::jsonb,0,'Trauma often disrupts sleep, mood, and behavior.','original'),
('127.311.d.2.A',4,'A trauma-affected preschooler is most likely to show:','["strong peer leadership", "regression, such as bedwetting after being toilet trained", "improved focus", "advanced reading"]'::jsonb,1,'Young children often lose skills they already had after trauma.','original'),
('127.311.d.2.B',3,'A child who needs help coping with a family crisis might see a:','["tax preparer", "bus driver", "licensed child counselor", "librarian"]'::jsonb,2,'Counselors are trained to help children cope.','original'),
('127.311.d.2.B',4,'Play therapy is a counseling approach that helps young children:','["earn a driver''s license", "memorize facts", "learn tax rules", "express feelings through play"]'::jsonb,3,'Young children often show feelings through play rather than words.','original'),
('127.311.d.2.C',3,'Before giving first aid to an injured child, the first step is to:','["make sure the scene is safe", "give the child food", "move the child quickly", "wait an hour"]'::jsonb,0,'Rescuers must not become victims.','original'),
('127.311.d.2.C',4,'Rescue breaths and chest compressions given to a child who is not breathing are called:','["Triage", "CPR", "Rehydration", "The Heimlich maneuver"]'::jsonb,1,'CPR stands for cardiopulmonary resuscitation.','original'),
('127.311.d.2.D',3,'A family needing free health screenings for children could contact:','["a movie theater", "a shopping mall", "a community health clinic", "a car dealership"]'::jsonb,2,'Clinics offer low-cost or free child health services.','original'),
('127.311.d.2.D',4,'WIC, a program for mothers and young children, provides:','["car repairs", "college tuition", "housing vouchers", "nutritious foods and nutrition education"]'::jsonb,3,'WIC supports the nutrition of women, infants, and children.','original'),
('127.311.d.2.E',3,'Which is a recommended preventive health measure for children?','["Well-child checkups and immunizations", "Skipping dental visits", "Delaying vision screening", "Avoiding all exercise"]'::jsonb,0,'Regular checkups catch problems early.','original'),
('127.311.d.2.E',4,'Immunizations protect children by:','["replacing healthy food", "building protection against serious diseases", "curing every illness", "removing the need for handwashing"]'::jsonb,1,'Vaccines prepare the immune system before exposure.','original'),
('127.311.d.2.F',3,'A safe crib for an infant has:','["a blanket over the rails", "soft pillows and bumpers", "a firm mattress and no loose bedding", "stuffed animals piled inside"]'::jsonb,2,'Loose items raise the risk of suffocation.','original'),
('127.311.d.2.F',4,'A toy is a choking hazard for a toddler if it:','["is larger than a fist", "is made of soft cloth", "has a wide handle", "has small parts that fit through a toilet paper tube"]'::jsonb,3,'The toilet-paper-tube test checks for choking size.','original'),
('127.311.d.2.G',3,'Laws requiring children to ride in car seats are meant to:','["protect children from injury", "raise car prices", "limit travel", "reduce school time"]'::jsonb,0,'Restraint laws save lives.','original'),
('127.311.d.2.G',4,'A law that requires certain professionals to report suspected child abuse is called a:','["tariff", "mandatory reporting law", "curfew law", "zoning ordinance"]'::jsonb,1,'Mandated reporters must report suspected abuse.','original'),
('127.311.d.3.A',3,'A common early sign of pregnancy is:','["hearing loss", "a new tooth", "a missed menstrual period", "a sudden growth spurt"]'::jsonb,2,'A missed period is often the first sign.','original'),
('127.311.d.3.A',4,'Pregnancy is divided into three:','["quarters", "semesters", "seasons", "trimesters"]'::jsonb,3,'Each trimester is about three months.','original'),
('127.311.d.3.B',3,'Traits passed from parents to a child through genes are called:','["hereditary traits", "environmental traits", "cultural rules", "learned habits"]'::jsonb,0,'Heredity is the passing of genes.','original'),
('127.311.d.3.B',4,'Which is an environmental factor that can affect a pregnancy?','["Chromosome number", "Exposure to secondhand smoke", "Eye color", "Blood type"]'::jsonb,1,'Smoke exposure is environmental, not inherited.','original'),
('127.311.d.3.C',3,'A birth defect is a problem with the body or its function that is present:','["only in adulthood", "after puberty", "at birth", "after age five"]'::jsonb,2,'Birth defects form before the baby is born.','original'),
('127.311.d.3.C',4,'Taking folic acid before and during early pregnancy can lower the risk of:','["tooth decay", "growth spurts", "common colds", "neural tube defects"]'::jsonb,3,'Folic acid helps the neural tube close.','original'),
('127.311.d.3.D',3,'Which nutrient is especially important to help prevent neural tube defects during pregnancy?','["Folic acid", "Caffeine", "Sugar", "Sodium"]'::jsonb,0,'Folic acid supports early fetal development.','original'),
('127.311.d.3.D',4,'A pregnant woman needs extra calcium mainly to help:','["slow the baby''s growth", "build the baby''s bones and teeth", "lower the baby''s weight", "prevent labor"]'::jsonb,1,'Calcium supports skeletal development.','original'),
('127.311.d.3.E',3,'Regular visits to a health care provider during pregnancy are called:','["emergency care", "postnatal care", "prenatal care", "dental care"]'::jsonb,2,'Prenatal means before birth.','original'),
('127.311.d.3.E',4,'Which habit is part of good health practices before and during pregnancy?','["Eating only snacks", "Skipping checkups", "Avoiding all movement", "Avoiding alcohol, tobacco, and illegal drugs"]'::jsonb,3,'These substances can harm a developing baby.','original'),
('127.311.d.3.F',3,'A prenatal ultrasound uses sound waves to:','["create an image of the developing baby", "start labor", "change the baby''s genes", "deliver nutrients"]'::jsonb,0,'Ultrasound shows growth and position.','original'),
('127.311.d.3.F',4,'Technology such as prenatal screening tests can help families by:','["preventing all birth defects", "detecting some health concerns early", "replacing doctor visits", "guaranteeing a healthy baby"]'::jsonb,1,'Screening finds possible problems but cannot guarantee outcomes.','original'),
('127.311.d.3.G',3,'Which professional provides care to women during pregnancy and delivers babies?','["Orthodontist", "Dermatologist", "Obstetrician", "Podiatrist"]'::jsonb,2,'Obstetricians specialize in pregnancy and childbirth.','original'),
('127.311.d.3.G',4,'A doula''s main role is to:','["read X-rays", "perform surgery", "prescribe medicine", "give physical and emotional support during pregnancy and birth"]'::jsonb,3,'Doulas provide non-medical support.','original'),
('127.311.d.3.H',3,'A cesarean section is a delivery method in which the baby is born:','["through a surgical incision", "through the birth canal", "at home with no help", "after a week of labor"]'::jsonb,0,'C-sections are surgical deliveries.','original'),
('127.311.d.3.H',4,'The three stages of labor are, in order:','["delivery of the placenta, dilation, delivery of the baby", "dilation, delivery of the baby, delivery of the placenta", "delivery of the baby, dilation, delivery of the placenta", "delivery of the baby, delivery of the placenta, dilation"]'::jsonb,1,'The cervix dilates, the baby is born, then the placenta is delivered.','original'),
('127.311.d.4.A',3,'A 6-month-old who begins to sit with support and reach for objects is showing growth in:','["moral reasoning", "financial skills", "physical development", "abstract thinking"]'::jsonb,2,'Sitting and reaching are motor milestones.','original'),
('127.311.d.4.A',4,'Which of these is an emotional milestone for infants in the first year?','["Debating rules", "Sharing toys fairly", "Writing their name", "Showing attachment to a caregiver"]'::jsonb,3,'Infants form bonds with caregivers.','original'),
('127.311.d.4.B',3,'The arrival of a new baby can affect a family by:','["changing routines, sleep, and finances", "lowering every expense", "ending all responsibilities", "removing the need for planning"]'::jsonb,0,'A baby changes daily life and costs.','original'),
('127.311.d.4.B',4,'Parents of a newborn often feel tired because infants:','["feed only once daily", "need frequent feeding and care throughout the night", "sleep through the night", "need no attention"]'::jsonb,1,'Newborns wake often to eat.','original'),
('127.311.d.4.C',3,'Experts advise limiting screen time for infants because babies learn best from:','["using tablets alone", "listening to loud music", "interacting with caring people", "watching fast videos"]'::jsonb,2,'Responsive interaction drives infant learning.','original'),
('127.311.d.4.C',4,'An assistive technology that could help an infant with hearing loss is:','["a night light", "a calculator", "a play mat", "a hearing aid"]'::jsonb,3,'Hearing aids amplify sound.','original'),
('127.311.d.4.D',3,'A pediatric nurse works with:','["infants, children, and teens", "only animals", "only athletes", "only older adults"]'::jsonb,0,'Pediatrics focuses on young patients.','original'),
('127.311.d.4.D',4,'A person who cares for infants in a licensed child care center is called an:','["accountant", "infant caregiver", "air traffic controller", "architect"]'::jsonb,1,'Infant caregivers meet babies'' daily needs.','original'),
('127.311.d.4.E',3,'For the first months of life, an infant''s main nutrition should come from:','["solid steak", "fruit juice", "breast milk or iron-fortified formula", "cow''s milk only"]'::jsonb,2,'Milk or formula meets early needs.','original'),
('127.311.d.4.E',4,'Honey should not be given to infants under 12 months because it can cause:','["faster growth", "wheat allergies", "tooth whitening", "infant botulism"]'::jsonb,3,'Honey can carry botulism spores.','original'),
('127.311.d.5.A',3,'A toddler who takes first steps and begins to run is showing growth in:','["physical development", "abstract thinking", "moral reasoning", "algebra skills"]'::jsonb,0,'Walking and running are motor skills.','original'),
('127.311.d.5.A',4,'A toddler who says ''no'' and ''mine'' often is developing:','["adult friendships", "a sense of independence", "abstract reasoning", "career interest"]'::jsonb,1,'Toddlers assert themselves as they gain autonomy.','original'),
('127.311.d.5.B',3,'Reading picture books and singing nursery rhymes with a toddler are play activities that build:','["tax skills", "driving skills", "pre-literacy skills", "financial skills"]'::jsonb,2,'Language play prepares children for reading.','original'),
('127.311.d.5.B',4,'Which play activity best builds social-emotional learning for toddlers?','["Solving algebra", "Writing paragraphs", "Memorizing multiplication facts", "Taking turns with a ball and naming feelings"]'::jsonb,3,'Turn-taking and naming feelings teach social skills.','original'),
('127.311.d.5.C',3,'For toddlers, which type of screen use is most beneficial?','["Video chatting with a family member", "Hours of unsupervised videos", "Playing adult games", "Fast-paced violent shows"]'::jsonb,0,'Interactive, live contact supports learning.','original'),
('127.311.d.5.C',4,'A speech-generating tablet that helps a toddler communicate is an example of:','["passive viewing", "assistive technology", "a toy only", "a learning disability"]'::jsonb,1,'Assistive technology supports a child''s abilities.','original'),
('127.311.d.5.D',3,'Which food is a choking hazard for toddlers and should be cut up or avoided?','["Mashed potatoes", "Yogurt", "Whole grapes", "Cooked rice"]'::jsonb,2,'Round, firm foods can block the airway.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_54_v1'
